import React, { useContext, useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import styles from './ProductForm.module.css';
import { AuthContext } from '../../context/AuthContext';
import { useNotifications } from '../../context/NotificationContext';

function ProductForm() {
    const { token, user } = useContext(AuthContext);
    const navigate = useNavigate();
    const { id } = useParams();
    const { showSuccess, showError, showInfo } = useNotifications();

    const isEdit = Boolean(id);

    const [formData, setFormData] = useState({
        name: '',
        sku: '',
        description: '',
        category: '',
        animalType: [],
        currentPrice: '',
        unit: 'шт',
        stockQuantity: 0,
        minStockLevel: 10,
        imageUrl: '',
        inStock: true
    });

    const [loading, setLoading] = useState(false);
    const [initialLoading, setInitialLoading] = useState(isEdit); // только для загрузки при редактировании

    useEffect(() => {
        if (isEdit) {
            setInitialLoading(true);
            fetch(`http://localhost:5000/api/products/${id}`)
                .then(res => res.json())
                .then(data => {
                    console.log('Данные с сервера:', data); // для отладки
                    if (data.success && data.data.product) {
                        const productData = data.data.product;

                        // ВАЖНО: Преобразуем все значения в нужный формат
                        setFormData({
                            name: productData.name || '',
                            sku: productData.sku || '',
                            description: productData.description || '',
                            category: productData.category || '',
                            animalType: Array.isArray(productData.animalType)
                                ? productData.animalType
                                : (productData.animalType ? [productData.animalType] : []),
                            currentPrice: productData.currentPrice?.toString() || '',
                            unit: productData.unit || 'шт',
                            stockQuantity: productData.stockQuantity?.toString() || '0',
                            minStockLevel: productData.minStockLevel?.toString() || '10',
                            imageUrl: productData.imageUrl || '',
                            inStock: productData.inStock !== undefined ? productData.inStock : true
                        });
                        console.log('Установлены данные формы:', {
                            ...formData,
                            animalType: productData.animalType,
                            currentPrice: productData.currentPrice?.toString()
                        });
                    } else {
                        showError('Не удалось загрузить данные продукта');
                    }
                })
                .catch((error) => {
                    console.error('Ошибка загрузки:', error);
                    showError('Ошибка загрузки продукта');
                })
                .finally(() => setInitialLoading(false));
        }
    }, [id, isEdit]);

    const handleChange = (e) => {
        const { name, value, type } = e.target;

        // Обработка числовых полей
        if (name === 'currentPrice' || name === 'stockQuantity' || name === 'minStockLevel') {
            // Разрешаем пустую строку и числа
            const numValue = value === '' ? '' : value;
            setFormData(prev => ({ ...prev, [name]: numValue }));
        } else {
            setFormData(prev => ({ ...prev, [name]: value }));
        }
    };

    const handleAnimalTypeChange = (e) => {
        const options = Array.from(e.target.selectedOptions).map(opt => opt.value);
        console.log('Выбраны животные:', options); // для отладки
        setFormData(prev => ({ ...prev, animalType: options }));
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);

        console.log('Отправляемые данные:', formData); // для отладки

        // Валидация на клиенте
        const errors = [];

        if (!formData.name.trim()) errors.push('Название обязательно');
        if (!isEdit && !formData.sku.trim()) errors.push('Артикул обязателен');
        if (!formData.category) errors.push('Категория обязательна');
        if (!formData.animalType.length) errors.push('Выберите хотя бы один тип животного');
        if (!formData.currentPrice || parseFloat(formData.currentPrice) <= 0) errors.push('Цена должна быть больше 0');
        if (!formData.unit) errors.push('Единица измерения обязательна');

        if (errors.length > 0) {
            showError(errors.join(', '));
            setLoading(false);
            return;
        }

        const method = isEdit ? 'PUT' : 'POST';
        const url = isEdit
            ? `http://localhost:5000/api/products/${id}`
            : 'http://localhost:5000/api/products';

        // Формируем данные для отправки
        const requestData = {
            name: formData.name.trim(),
            description: formData.description.trim(),
            category: formData.category,
            animalType: formData.animalType,
            currentPrice: parseFloat(formData.currentPrice),
            unit: formData.unit,
            stockQuantity: parseInt(formData.stockQuantity) || 0,
            minStockLevel: parseInt(formData.minStockLevel) || 10,
            imageUrl: formData.imageUrl.trim() || 'https://via.placeholder.com/300x300?text=Pet+Product',
            inStock: formData.inStock
        };

        // Для создания добавляем SKU, для редактирования - нет
        if (!isEdit) {
            requestData.sku = formData.sku.trim().toUpperCase();
        }

        console.log('Отправляем на сервер:', requestData); // для отладки

        try {
            const res = await fetch(url, {
                method,
                headers: {
                    'Content-Type': 'application/json',
                    Authorization: `Bearer ${token}`
                },
                body: JSON.stringify(requestData)
            });

            const data = await res.json();
            console.log('Ответ сервера:', data); // для отладки

            if (data.success) {
                showSuccess(isEdit ? 'Продукт успешно обновлен!' : 'Продукт успешно создан! 🎉');
                setTimeout(() => navigate('/products'), 1500);
            } else {
                // Показываем детальную ошибку от сервера
                const errorMessage = data.message || data.details || 'Ошибка сохранения';
                showError(`Ошибка: ${errorMessage}`);
                setLoading(false);
            }
        } catch (error) {
            console.error('Ошибка сети:', error);
            showError('Ошибка подключения к серверу');
            setLoading(false);
        }
    };

    if (user?.role !== 'admin') {
        return <p className={styles.error}>Доступ запрещён</p>;
    }

    if (initialLoading) {
        return <div className={styles.loading}>Загрузка данных продукта...</div>;
    }

    return (
        <div className={styles.container}>
            <h2 className={styles.title}>
                {isEdit ? 'Редактировать продукт' : 'Создать продукт'}
            </h2>

            <form onSubmit={handleSubmit} className={styles.form}>
                <div className={styles.formGroup}>
                    <label htmlFor="name">Название *</label>
                    <input
                        id="name"
                        type="text"
                        name="name"
                        placeholder="Название товара"
                        value={formData.name}
                        onChange={handleChange}
                        required
                        disabled={loading}
                    />
                </div>

                {!isEdit ? (
                    <div className={styles.formGroup}>
                        <label htmlFor="sku">Артикул *</label>
                        <input
                            id="sku"
                            type="text"
                            name="sku"
                            placeholder="Уникальный артикул"
                            value={formData.sku}
                            onChange={handleChange}
                            required
                            disabled={loading}
                        />
                    </div>
                ) : (
                    <div className={styles.formGroup}>
                        <label htmlFor="sku">Артикул (только для просмотра)</label>
                        <input
                            id="sku"
                            type="text"
                            value={formData.sku}
                            disabled
                            className={styles.readonly}
                        />
                    </div>
                )}

                <div className={styles.formGroup}>
                    <label htmlFor="description">Описание</label>
                    <textarea
                        id="description"
                        name="description"
                        placeholder="Описание товара"
                        value={formData.description}
                        onChange={handleChange}
                        disabled={loading}
                        rows={3}
                    />
                </div>

                <div className={styles.formGroup}>
                    <label htmlFor="category">Категория *</label>
                    <select
                        id="category"
                        name="category"
                        value={formData.category}
                        onChange={handleChange}
                        required
                        disabled={loading}
                    >
                        <option value="">Выберите категорию</option>
                        <option value="Корма">Корма</option>
                        <option value="Аксессуары">Аксессуары</option>
                        <option value="Игрушки">Игрушки</option>
                        <option value="Здоровье">Здоровье</option>
                        <option value="Гигиена">Гигиена</option>
                        <option value="Переноски">Переноски</option>
                        <option value="Одежда">Одежда</option>
                    </select>
                </div>

                <div className={styles.formGroup}>
                    <label htmlFor="animalType">Для животных * (удерживайте Ctrl для выбора нескольких)</label>
                    <select
                        id="animalType"
                        name="animalType"
                        multiple
                        value={formData.animalType}
                        onChange={handleAnimalTypeChange}
                        required
                        disabled={loading}
                        size={6}
                    >
                        <option value="Собака">Собака</option>
                        <option value="Кошка">Кошка</option>
                        <option value="Птица">Птица</option>
                        <option value="Рыбка">Рыбка</option>
                        <option value="Грызун">Грызун</option>
                        <option value="Рептилия">Рептилия</option>
                        <option value="Все">Все животные</option>
                    </select>
                    {formData.animalType.length > 0 && (
                        <div className={styles.selectedTypes}>
                            Выбрано: {formData.animalType.join(', ')}
                        </div>
                    )}
                </div>

                <div className={styles.formRow}>
                    <div className={styles.formGroup}>
                        <label htmlFor="currentPrice">Цена *</label>
                        <input
                            id="currentPrice"
                            type="number"
                            name="currentPrice"
                            placeholder="0.00"
                            value={formData.currentPrice}
                            onChange={handleChange}
                            required
                            min="0"
                            step="0.01"
                            disabled={loading}
                        />
                    </div>

                    <div className={styles.formGroup}>
                        <label htmlFor="unit">Единица измерения *</label>
                        <select
                            id="unit"
                            name="unit"
                            value={formData.unit}
                            onChange={handleChange}
                            required
                            disabled={loading}
                        >
                            <option value="шт">шт</option>
                            <option value="кг">кг</option>
                            <option value="л">л</option>
                            <option value="уп">уп</option>
                            <option value="г">г</option>
                        </select>
                    </div>
                </div>

                <div className={styles.formRow}>
                    <div className={styles.formGroup}>
                        <label htmlFor="stockQuantity">Количество на складе</label>
                        <input
                            id="stockQuantity"
                            type="number"
                            name="stockQuantity"
                            placeholder="0"
                            value={formData.stockQuantity}
                            onChange={handleChange}
                            min="0"
                            disabled={loading}
                        />
                    </div>

                    <div className={styles.formGroup}>
                        <label htmlFor="minStockLevel">Минимальный запас</label>
                        <input
                            id="minStockLevel"
                            type="number"
                            name="minStockLevel"
                            placeholder="10"
                            value={formData.minStockLevel}
                            onChange={handleChange}
                            min="0"
                            disabled={loading}
                        />
                    </div>
                </div>

                <div className={styles.formGroup}>
                    <label htmlFor="imageUrl">Ссылка на изображение</label>
                    <input
                        id="imageUrl"
                        type="text"
                        name="imageUrl"
                        placeholder="https://example.com/image.jpg"
                        value={formData.imageUrl}
                        onChange={handleChange}
                        disabled={loading}
                    />
                    {formData.imageUrl && (
                        <div className={styles.imagePreview}>
                            <small>Предпросмотр:</small>
                            <img
                                src={formData.imageUrl}
                                alt="Предпросмотр"
                                onError={(e) => {
                                    e.target.src = 'https://via.placeholder.com/100x100?text=Ошибка+загрузки';
                                }}
                            />
                        </div>
                    )}
                </div>

                <div className={styles.formGroup}>
                    <label className={styles.checkboxLabel}>
                        <input
                            type="checkbox"
                            name="inStock"
                            checked={formData.inStock}
                            onChange={(e) => setFormData(prev => ({
                                ...prev,
                                inStock: e.target.checked
                            }))}
                            disabled={loading}
                        />
                        <span>Товар в наличии</span>
                    </label>
                </div>

                <div className={styles.formActions}>
                    <button
                        type="button"
                        className={styles.cancelButton}
                        onClick={() => navigate('/products')}
                        disabled={loading}
                    >
                        Отмена
                    </button>
                    <button
                        type="submit"
                        className={styles.button}
                        disabled={loading}
                    >
                        {loading ? 'Сохранение...' : (isEdit ? 'Сохранить изменения' : 'Создать товар')}
                    </button>
                </div>
            </form>
        </div>
    );
}

export default ProductForm;
